% source-component p28-q15-sheet: Landscape rectangle representing an A4 sheet. Bold A4 is centred inside. The top horizontal side is labelled 297mm; the left vertical side is labelled 210mm, with rotated text. A right-pointing arrow leads to a short upright rolled cylinder. A downward arrow leads to a longer horizontal rolled cylinder.
% source-component p28-q15-long-curl: Short upright rolled sheet forming a cylinder, shown with a narrow longitudinal opening at the front and a visible elliptical upper rim. Caption: Curl up the long side.
% source-component p28-q15-short-curl: Long horizontal rolled sheet forming a cylinder, with a longitudinal opening and visible curved end at the right. Caption: Curl up the short side.
% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 28 p28-q15-rolling-diagram"}
\begin{tikzpicture}[x=1cm,y=1cm,line width=.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (SBL) at (0,2.5);\coordinate (SBR) at (3,2.5);\coordinate (STR) at (3,4.6212);\coordinate (STL) at (0,4.6212);
\draw (SBL)--(SBR)--(STR)--(STL)--cycle;
\path (STL)--node[above] {$297\,\mathrm{mm}$}(STR);
\path (SBL)--node[left,rotate=90,anchor=south] {$210\,\mathrm{mm}$}(STL);
\node[font=\bfseries\fontsize{10}{12}\selectfont] at (1.5,3.5606) {A4};
\draw[->,line width=.8pt] (3.3,3.7)--(3.85,3.7);
\draw[->,line width=.8pt] (1.5,2.28)--(1.5,1.75);
\begin{scope}[shift={(4.8,3.15)}]
\draw plot[domain=-80:260,samples=80] ({.7*cos(\x)},{1+.22*sin(\x)});
\draw plot[domain=180:260,samples=24] ({.7*cos(\x)},{.22*sin(\x)});
\draw plot[domain=280:360,samples=24] ({.7*cos(\x)},{.22*sin(\x)});
\draw (-.7,0)--(-.7,1) (.7,0)--(.7,1);
\draw ({.7*cos(260)},{.22*sin(260)})--++(0,1);
\draw ({.7*cos(280)},{.22*sin(280)})--++(0,1);
\node[below,align=center] at (0,-.35) {Curl up the long side};
\end{scope}
\begin{scope}[shift={(.35,.25)}]
\draw plot[domain=-80:260,samples=80] ({3+.22*sin(\x)},{.6*cos(\x)});
\draw plot[domain=180:260,samples=24] ({.22*sin(\x)},{.6*cos(\x)});
\draw plot[domain=280:360,samples=24] ({.22*sin(\x)},{.6*cos(\x)});
\draw (0,.6)--(3,.6) (0,-.6)--(3,-.6);
\draw ({.22*sin(260)},{.6*cos(260)})--++(3,0);
\draw ({.22*sin(280)},{.6*cos(280)})--++(3,0);
\node[below,align=center] at (1.5,-.78) {Curl up the short side};
\end{scope}
\end{tikzpicture}
